  '長野県::高山村': '長野県::高山村（長野県）',
  '福井県::美浜町': '福井県::美浜町（福井県）',
  '富山県::朝日町': '富山県::朝日町（富山県）',
  '大阪府::太子町': '大阪府::太子町（大阪府）',
  '長野県::川上村': '長野県::川上村（長野県）',
  '山梨県::南部町': '山梨県::南部町（山梨県）',
  '滋賀県::日野町': '滋賀県::日野町（滋賀県）',
  '和歌山県::広川町': '和歌山県::広川町（和歌山県）',
  '長野県::高森町': '長野県::高森町（長野県）',
  '島根県::美郷町': '島根県::美郷町（島根県）',
  '愛媛県::松前町': '愛媛県::松前町（愛媛県）',
  '静岡県::森町': '静岡県::森町（静岡県）',
  '和歌山県::日高町': '和歌山県::日高町（和歌山県）',
  '静岡県::清水町': '静岡県::清水町（静岡県）',
  '青森県::南部町': '青森県::南部町（青森県）',
  '熊本県::美里町': '熊本県::美里町（熊本県）',
  '山形県::朝日町': '山形県::朝日町（山形県）',
  '山形県::小国町': '山形県::小国町（山形県）',
  '熊本県::小国町': '熊本県::小国町（熊本県）',
  '山形県::川西町': '山形県::川西町（山形県）',
  '奈良県::川西町': '奈良県::川西町（奈良県）',
  '宮城県::川崎町': '宮城県::川崎町（宮城県）',
  '福岡県::川崎町': '福岡県::川崎町（福岡県）',
  '山形県::金山町': '山形県::金山町（山形県）',
  '福島県::金山町': '福島県::金山町（福島県）',
  '秋田県::美郷町': '秋田県::美郷町（秋田県）',
  '群馬県::南牧村': '群馬県::南牧村（群馬県）',
  '長野県::南牧村': '長野県::南牧村（長野県）',
  '群馬県::明和町': '群馬県::明和町（群馬県）',
  '三重県::明和町': '三重県::明和町（三重県）',
  '群馬県::昭和村': '群馬県::昭和村（群馬県）',
  '福島県::昭和村': '福島県::昭和村（福島県）',
  '群馬県::高山村': '群馬県::高山村（群馬県）',
  '埼玉県::美里町': '埼玉県::美里町（埼玉県）',
  '宮城県::美里町': '宮城県::美里町（宮城県）',
