// 記録オブジェクト(キーがcityId)の旧キーを新キーへ移す。変更があればtrueを返す。
// 新旧どちらの記録もある場合は、より良い記録(最短質問数が少ないほう)を残してまとめる。
function migrateCityIdKeys(bucket, mergeEntry){
  if(!bucket || typeof bucket !== 'object') return false;
  let changed = false;
  for(const oldId in CITY_ID_MIGRATION){
    if(!Object.prototype.hasOwnProperty.call(bucket, oldId)) continue;
    const newId = CITY_ID_MIGRATION[oldId];
    const oldVal = bucket[oldId];
    bucket[newId] = Object.prototype.hasOwnProperty.call(bucket, newId) && mergeEntry
      ? mergeEntry(bucket[newId], oldVal)
      : (Object.prototype.hasOwnProperty.call(bucket, newId) ? bucket[newId] : oldVal);
    delete bucket[oldId];
    changed = true;
  }
  return changed;
}

// 制覇帳エントリ用のまとめ方(同じ自治体の記録が新旧に分かれていた場合)
function mergeConquestEntries(a, b){
  if(!a || typeof a !== 'object') return b;
  if(!b || typeof b !== 'object') return a;
  return {
    ...a,
    firstAt: (a.firstAt && b.firstAt) ? (a.firstAt < b.firstAt ? a.firstAt : b.firstAt) : (a.firstAt || b.firstAt),
    lastAt:  (a.lastAt && b.lastAt)  ? (a.lastAt  > b.lastAt  ? a.lastAt  : b.lastAt)  : (a.lastAt  || b.lastAt),
    count: (Number(a.count) || 0) + (Number(b.count) || 0),
    minQuestions: Math.min(
      Number.isFinite(a.minQuestions) ? a.minQuestions : Infinity,
      Number.isFinite(b.minQuestions) ? b.minQuestions : Infinity),
    modes: [...new Set([...(a.modes || []), ...(b.modes || [])])],
  };
}

// localStorageや読み込みファイルは利用者が書き換えられるため、そのまま表示には使わない。
// 自治体名・都道府県名は必ず現在のcities.jsonから引き直し、数値や日時も安全な型へ整える。
// strict=trueはセーブデータ読み込み用で、1件でも不正なら全体を拒否する。
function normalizeConquestData(rawConquest, strict){
  const fail = reason => ({ ok: false, reason });
  if(!rawConquest || typeof rawConquest !== 'object' || Array.isArray(rawConquest)
     || !rawConquest.entries || typeof rawConquest.entries !== 'object' || Array.isArray(rawConquest.entries)){
    return fail('制覇帳のデータが見つかりません。');
  }

  const rawIds = Object.keys(rawConquest.entries);
  if(rawIds.length > 2000) return fail('自治体データの件数が多すぎます。');

  // Object.prototypeを持たない入れ物へ移してから旧ID migrationを行う。
  // "__proto__"等を含む細工されたJSONでもprototypeを変更させない。
  const migratedEntries = Object.create(null);
  rawIds.forEach(id => {
    if(typeof id === 'string' && id.length <= 100){
      migratedEntries[id] = rawConquest.entries[id];
    }
  });
  migrateCityIdKeys(migratedEntries, mergeConquestEntries);

  const cityById = new Map(CITIES.map(city => [cityId(city), city]));
  const validModes = new Set(Object.keys(MODES));
  const normalizedEntries = {};
  for(const id of Object.keys(migratedEntries)){
    const raw = migratedEntries[id];
    const city = cityById.get(id);
    const invalid = !city || !raw || typeof raw !== 'object' || Array.isArray(raw)
      || !Number.isInteger(raw.count) || raw.count < 1 || raw.count > 1000000
      || !Number.isInteger(raw.minQuestions) || raw.minQuestions < 1 || raw.minQuestions > 1000
      || !Array.isArray(raw.modes) || raw.modes.length > 30;
    if(invalid){
      if(strict) return fail('制覇帳データの内容が壊れています。');
      continue;
    }

    const modes = [...new Set(raw.modes.filter(mode => typeof mode === 'string' && validModes.has(mode)))];
    if(strict && modes.length !== raw.modes.length){
      return fail('認識できないゲームモードが含まれています。');
    }

    const firstAtMs = typeof raw.firstAt === 'string' ? Date.parse(raw.firstAt) : NaN;
    const lastAtMs = typeof raw.lastAt === 'string' ? Date.parse(raw.lastAt) : NaN;
    if(strict && (!Number.isFinite(firstAtMs) || !Number.isFinite(lastAtMs))){
      return fail('制覇帳データの日時が壊れています。');
    }
    const firstAt = Number.isFinite(firstAtMs) ? new Date(firstAtMs).toISOString() : new Date(0).toISOString();
    const lastAt = Number.isFinite(lastAtMs) ? new Date(lastAtMs).toISOString() : firstAt;

    normalizedEntries[id] = {
      id,
      name: displayName(city),
      pref: city.pref,
      firstAt,
      lastAt,
      count: raw.count,
      minQuestions: raw.minQuestions,
      modes,
    };
  }

  return {
    ok: true,
    conquest: { version: CONQUEST_VERSION, entries: normalizedEntries }
  };
}

// ==================== localStorage: 設定(匿名送信) ====================
const SETTINGS_STORAGE_KEY = 'oramachi_settings_v1';
const SETTINGS_VERSION = 1;
// 初期値はON(既存の「最近当てられたマチ」「プレイ回数」表示が、
// 導入前と変わらず引き続き機能するようにするため)。設定画面でいつでもOFFにできる。
const DEFAULT_SETTINGS = { version: SETTINGS_VERSION, anonymousReporting: true };

function loadSettings(){
  try{
    const raw = localStorage.getItem(SETTINGS_STORAGE_KEY);
    if(!raw) return { ...DEFAULT_SETTINGS };
    const parsed = JSON.parse(raw);
    if(!parsed || typeof parsed !== 'object' || parsed.version !== SETTINGS_VERSION){
      // 破損・旧バージョンのデータを検出した時点で、localStorage側も安全な初期値に書き戻しておく
      saveSettings(DEFAULT_SETTINGS);
      return { ...DEFAULT_SETTINGS };
    }
    return { ...DEFAULT_SETTINGS, ...parsed };
  }catch(e){
    console.warn('おらマチ: 設定データの読み込みに失敗したため初期値を使います', e);
    try{ saveSettings(DEFAULT_SETTINGS); }catch(e2){ /* 保存も失敗する場合は諦める(ゲーム自体は継続) */ }
    return { ...DEFAULT_SETTINGS };
  }
}
function saveSettings(settings){
  try{
    localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(settings));
  }catch(e){
    console.warn('おらマチ: 設定の保存に失敗しました(localStorageが使えない可能性があります)', e);
  }
}
let appSettings = loadSettings();
function isAnonymousReportingEnabled(){
  return !!appSettings.anonymousReporting;
}

// ==================== localStorage: 全国制覇帳 ====================
const CONQUEST_STORAGE_KEY = 'oramachi_conquest_v1';
const CONQUEST_VERSION = 1;
function emptyConquestData(){
  return { version: CONQUEST_VERSION, entries: {} };
}
function loadConquest(){
  try{
    const raw = localStorage.getItem(CONQUEST_STORAGE_KEY);
    if(!raw) return emptyConquestData();
    const parsed = JSON.parse(raw);
    if(!parsed || typeof parsed !== 'object' || parsed.version !== CONQUEST_VERSION
       || typeof parsed.entries !== 'object' || parsed.entries === null){
      console.warn('おらマチ: 制覇帳データの形式が不正なため、初期化します');
      const empty = emptyConquestData();
      saveConquest(empty); // localStorage側も安全な状態に書き戻しておく
      return empty;
    }
    const normalized = normalizeConquestData(parsed, false);
    if(!normalized.ok){
      const empty = emptyConquestData();
      saveConquest(empty);
      return empty;
    }
    // 旧形式、壊れた項目、表示名の改ざん等があれば、安全な正規形へ一度だけ書き戻す。
    const normalizedData = normalized.conquest;
    if(JSON.stringify(parsed) !== JSON.stringify(normalizedData)){
      try{ saveConquest(normalizedData); }catch(e){ /* 保存に失敗してもゲームは続行する */ }
    }
    return normalizedData;
  }catch(e){
    console.warn('おらマチ: 制覇帳データの読み込みに失敗したため初期化します(破損データの可能性)', e);
    const empty = emptyConquestData();
    try{ saveConquest(empty); }catch(e2){ /* 保存も失敗する場合は諦める(ゲーム自体は継続) */ }
    return empty;
  }
}
function saveConquest(data){
  try{
    localStorage.setItem(CONQUEST_STORAGE_KEY, JSON.stringify(data));
    scheduleSupabaseProgressSync();
    return true;
  }catch(e){
    console.warn('おらマチ: 制覇帳の保存に失敗しました(localStorageの容量不足などの可能性)', e);
    return false;
  }
}

// ==================== localStorage: プレイ統計・称号 ====================
// 自治体ごとの正解回数・最少質問数・都道府県などは、既に全国制覇帳(oramachi_conquest_v1)
// が持っているため、ここでは重複させず、称号判定のときに制覇帳データを直接参照する。
const STATS_STORAGE_KEY = 'oramachi_stats_v1';
const STATS_VERSION = 1;
function emptyStatsData(){
  return {
    version: STATS_VERSION,
    totalPlays: 0,                 // 累計プレイ回数(結果が確定した回数。成功・諦めの両方を含む)
    totalCorrect: 0,                // 累計正解回数
    currentStreak: 0,               // 現在の連続正解数
    maxStreak: 0,                   // 最高連続正解数
    playedDates: [],                // プレイした日付(YYYY-MM-DD、日本時間)の一覧。重複なし
    answerCounts: { yes: 0, no: 0, maybeYes: 0, maybeNo: 0, unknown: 0 }, // 回答種別の累計回数
    firstGuessCorrectCount: 0,      // 最初の推測で正解した回数
    laterGuessCorrectCount: 0,      // 2回目以降(追加質問後)の推測で正解した回数
    extraQuestionCorrectCount: 0,   // 追加質問を経て正解した回数(laterGuessCorrectCountとほぼ同義だが明示的に持つ)
    maxQuestionReachedCount: 0,     // 合計質問数が30問に到達した回数
    misguessedCityCounts: {},       // 自治体ID -> このゲームで過去に誤推測(「ちがう」)された回数
    unlockedAchievements: {},       // 称号ID -> { unlockedAt: ISO日時 }
    achievementOrder: [],           // 称号を獲得した順番(称号IDの配列)
    lastResult: null,               // 直近の正解: { city, pref, at }
    recentRegions: [],              // 直近に正解した都道府県名(隣接判定の隠し称号用。最大3件保持)
    // 【今回追加】称号拡充のための追加フィールド。既存フィールドの意味・型は一切変えていない。
    shareCount: 0,                  // シェア操作(画像・X文章)を実際に行った回数
    mapViewCount: 0,                // 結果画面の地図を表示した回数
    statsPageViewedAt: null,        // 統計ページを初めて見たISO日時(null=未閲覧)
    personalBestUpdateCount: 0,     // 自己最短記録を更新した回数(初回登録は含まない)
  };
}
function loadStats(){
  try{
    const raw = localStorage.getItem(STATS_STORAGE_KEY);
    if(!raw) return emptyStatsData();
    const parsed = JSON.parse(raw);
    if(!parsed || typeof parsed !== 'object' || parsed.version !== STATS_VERSION){
      console.warn('おらマチ: プレイ統計データの形式が不正なため、初期化します');
      const empty = emptyStatsData();
      saveStats(empty);
      return empty;
    }
    // 古いバージョンや部分的なデータでも安全に動くよう、既定値とマージする
    const merged = { ...emptyStatsData(), ...parsed };
    merged.answerCounts = { ...emptyStatsData().answerCounts, ...(parsed.answerCounts || {}) };
    // 同名自治体の表示名変更にあわせて、誤答回数の記録のキーも移し替える
    if(merged.misguessedCityCounts && typeof merged.misguessedCityCounts === 'object'){
      if(migrateCityIdKeys(merged.misguessedCityCounts, (a, b) => (Number(a) || 0) + (Number(b) || 0))){
        try{ saveStats(merged); }catch(e){ /* 保存に失敗してもゲームは続行する */ }
      }
    }
    if(!Array.isArray(merged.playedDates)) merged.playedDates = [];
    if(!Array.isArray(merged.achievementOrder)) merged.achievementOrder = [];
    if(!Array.isArray(merged.recentRegions)) merged.recentRegions = [];
    if(typeof merged.unlockedAchievements !== 'object' || merged.unlockedAchievements === null) merged.unlockedAchievements = {};
    if(typeof merged.misguessedCityCounts !== 'object' || merged.misguessedCityCounts === null) merged.misguessedCityCounts = {};
    // 数値フィールドが壊れている(NaN・文字列など)場合は0にフォールバックし、正解回数などがNaNにならないようにする
    ['totalPlays','totalCorrect','currentStreak','maxStreak','firstGuessCorrectCount',
     'laterGuessCorrectCount','extraQuestionCorrectCount','maxQuestionReachedCount',
     'shareCount','mapViewCount','personalBestUpdateCount'].forEach(k => {
      if(!Number.isFinite(merged[k])) merged[k] = 0;
    });
    ['yes','no','maybeYes','maybeNo','unknown'].forEach(k => {
      if(!Number.isFinite(merged.answerCounts[k])) merged.answerCounts[k] = 0;
    });
    return merged;
  }catch(e){
    console.warn('おらマチ: プレイ統計データの読み込みに失敗したため初期化します(破損データの可能性)', e);
    const empty = emptyStatsData();
    try{ saveStats(empty); }catch(e2){ /* 保存も失敗する場合は諦める(ゲーム自体は継続) */ }
    return empty;
  }
}
function saveStats(data){
  try{
    localStorage.setItem(STATS_STORAGE_KEY, JSON.stringify(data));
    scheduleSupabaseProgressSync();
    return true;
  }catch(e){
    console.warn('おらマチ: プレイ統計の保存に失敗しました(localStorageの容量不足などの可能性)', e);
    return false;
  }
}

// ==================== Android版: クリア評価とプレイヤーランク ====================
// 1回ごとの上手さは「クリア評価 S〜E」、長期的な全国攻略の実績は
// 「プレイヤーランク G〜S」として分ける。回答速度はどちらの採点にも使わない。
// ブラウザ版の画面は変えず、クリア評価はAndroid版の全国版だけに記録する。
const NATIVE_RANK_STORAGE_KEY = 'oramachi_rank_results_v1';
const NATIVE_RANK_STORAGE_VERSION = 1;
const NATIVE_RANK_RULES_VERSION = 2;
const NATIVE_RANK_HISTORY_LIMIT = 50;
const NATIVE_RANK_GRADES = Object.freeze(['S','A','B','C','D','E']);
const NATIVE_PLAYER_RANK_ART = Object.freeze({
  G:'native-player-rank-g.webp',
  F:'native-player-rank-f.webp',
  E:'native-player-rank-e.webp',
  D:'native-player-rank-d.webp',
  C:'native-player-rank-c.webp',
  B:'native-player-rank-b.webp',
  A:'native-player-rank-a.webp',
  S:'native-player-rank-s.webp',
});
const NATIVE_PLAYER_RANKS = Object.freeze([
  Object.freeze({ grade:'G', minScore:0,  title:'マチあるきビギナー' }),
  Object.freeze({ grade:'F', minScore:10, title:'ご近所ものしり' }),
  Object.freeze({ grade:'E', minScore:20, title:'まちあて見習い' }),
  Object.freeze({ grade:'D', minScore:30, title:'地方探訪家' }),
  Object.freeze({ grade:'C', minScore:45, title:'全国マチめぐり人' }),
  Object.freeze({ grade:'B', minScore:60, title:'自治体博士' }),
  Object.freeze({ grade:'A', minScore:75, title:'おらマチ名人' }),
  Object.freeze({ grade:'S', minScore:90, title:'日本全国マチマスター' }),
]);

function clampNumber(value, min, max){
  return Math.min(max, Math.max(min, value));
}

function nativeRankGradeForScore(score){
  const n = clampNumber(Math.round(Number(score) || 0), 0, 100);
  if(n >= 90) return 'S';
  if(n >= 80) return 'A';
  if(n >= 70) return 'B';
  if(n >= 60) return 'C';
  if(n >= 50) return 'D';
  return 'E';
}

function nativeRankQuestionScore(totalQuestions){
  const questions = clampNumber(Math.floor(Number(totalQuestions) || 0), 0, 80);
  if(questions <= 10) return 90;
  if(questions <= 15) return 80;
  if(questions <= 20) return 70;
  if(questions <= 26) return 60;
  if(questions <= 34) return 50;
  return 40;
}

// 現時点で全自治体に揃っている客観データは人口のため、人口順位を11段階に分けて
// 0〜10点を加える。人口が同じ自治体は必ず同じ点になり、データ更新までは値が変わらない。
let nativeMunicipalityDifficultyCache = null;
function nativeMunicipalityDifficultyBonus(city){
  const population = city && city.stats && Number(city.stats.population);
  if(!Number.isFinite(population) || population < 0) return 0;
  if(!nativeMunicipalityDifficultyCache
    || nativeMunicipalityDifficultyCache.source !== CITIES
    || nativeMunicipalityDifficultyCache.length !== CITIES.length){
    const populationCities = CITIES.filter(candidate =>
      candidate && candidate.name !== '東京' && candidate.stats &&
      Number.isFinite(Number(candidate.stats.population)) && Number(candidate.stats.population) >= 0
    );
    const counts = new Map();
    populationCities.forEach(candidate => {
      const value = Number(candidate.stats.population);
      counts.set(value, (counts.get(value) || 0) + 1);
    });
    const bonusByPopulation = new Map();
    let greaterCount = 0;
    Array.from(counts.keys()).sort((a, b) => b - a).forEach(value => {
      bonusByPopulation.set(value, Math.min(10, Math.floor(11 * greaterCount / populationCities.length)));
      greaterCount += counts.get(value);
    });
    nativeMunicipalityDifficultyCache = {
      source:CITIES,
      length:CITIES.length,
      bonusByPopulation,
    };
  }
  return nativeMunicipalityDifficultyCache.bonusByPopulation.get(population) || 0;
}

function nativeMunicipalityDifficultyLevel(city){
  return Math.min(5, Math.floor(nativeMunicipalityDifficultyBonus(city) / 2) + 1);
}

function nativeMunicipalityDifficultyPoints(cityOrLevel){
  const level = typeof cityOrLevel === 'number'
    ? clampNumber(Math.floor(cityOrLevel), 1, 5)
    : nativeMunicipalityDifficultyLevel(cityOrLevel);
  return [0, 10, 15, 25, 40, 60][level];
}

// 難しい自治体は、クリア評価を最大1段階ほど押し上げる。
function nativeClearDifficultyBonus(level){
  return [0, 0, 1, 3, 5, 10][clampNumber(Math.floor(Number(level) || 1), 1, 5)];
}

function calculateNativeRankResult(city, totalQuestions, answerLogSnapshot, context){
  const questions = clampNumber(Math.floor(Number(totalQuestions) || 0), 0, 80);
  const timings = (Array.isArray(answerLogSnapshot) ? answerLogSnapshot : [])
    .map(entry => entry && entry.responseMs)
    .filter(value => Number.isFinite(value) && value >= 0 && value <= 30000);
  const elapsedMs = timings.length > 0
    ? Math.round(timings.reduce((sum, value) => sum + value, 0))
    : null;
  const questionScore = nativeRankQuestionScore(questions);
  const difficultyLevel = nativeMunicipalityDifficultyLevel(city);
  const difficultyBonus = nativeClearDifficultyBonus(difficultyLevel);
  const totalScore = clampNumber(questionScore + difficultyBonus, 0, 100);
  const details = context && typeof context === 'object' ? context : {};
  const unknownCount = (Array.isArray(answerLogSnapshot) ? answerLogSnapshot : [])
    .reduce((count, entry) => count + (entry && entry.val === null ? 1 : 0), 0);
  return {
    playedAt: new Date().toISOString(),
    roomId: null,
    cityId: cityId(city),
    cityName: displayName(city),
    pref: city.pref,
    mode: 'all',
    success: true,
    questionCount: questions,
    elapsedMs,
    questionScore,
    timeScore: 0,
    populationDifficultyBonus: nativeMunicipalityDifficultyBonus(city),
    difficultyLevel,
    difficultyPoints: nativeMunicipalityDifficultyPoints(difficultyLevel),
    difficultyBonus,
    totalScore,
    grade: nativeRankGradeForScore(totalScore),
    wrongGuessCount: clampNumber(Math.floor(Number(details.wrongGuessCount) || 0), 0, 3),
    unknownCount,
    firstClear: details.firstClear === true,
    personalBest: details.personalBest === true,
    detailsAvailable: true,
    rankRulesVersion: NATIVE_RANK_RULES_VERSION,
    citiesVersion: typeof CITIES_VERSION === 'string' ? CITIES_VERSION : '',
  };
}

function normalizeNativeRankRecord(raw){
  if(!raw || typeof raw !== 'object' || raw.mode !== 'all' || raw.success !== true) return null;
  // 旧版(回答速度を含むA〜G方式)も捨てず、質問数と自治体難易度だけで再評価する。
  if(raw.rankRulesVersion !== 1 && raw.rankRulesVersion !== NATIVE_RANK_RULES_VERSION) return null;
  if(typeof raw.cityId !== 'string') return null;
  const city = CITIES.find(candidate => candidate.name !== '東京' && cityId(candidate) === raw.cityId);
  if(!city) return null;
  const questionCount = Number(raw.questionCount);
  if(!Number.isInteger(questionCount) || questionCount < 0 || questionCount > 80) return null;
  const elapsedMs = raw.elapsedMs == null ? null : Number(raw.elapsedMs);
  if(elapsedMs != null && (!Number.isFinite(elapsedMs) || elapsedMs < 0 || elapsedMs > 80 * 30000)) return null;
  const playedAtMs = Date.parse(raw.playedAt);
  if(!Number.isFinite(playedAtMs)) return null;
  const questionScore = nativeRankQuestionScore(questionCount);
  const difficultyLevel = nativeMunicipalityDifficultyLevel(city);
  const difficultyBonus = nativeClearDifficultyBonus(difficultyLevel);
  const totalScore = clampNumber(questionScore + difficultyBonus, 0, 100);
  const detailsAvailable = raw.rankRulesVersion === NATIVE_RANK_RULES_VERSION && raw.detailsAvailable !== false;
  return {
    playedAt: new Date(playedAtMs).toISOString(),
    roomId: null,
    cityId: cityId(city),
    cityName: displayName(city),
    pref: city.pref,
    mode: 'all',
    success: true,
    questionCount,
    elapsedMs,
    questionScore,
    timeScore: 0,
    populationDifficultyBonus: nativeMunicipalityDifficultyBonus(city),
    difficultyLevel,
    difficultyPoints: nativeMunicipalityDifficultyPoints(difficultyLevel),
    difficultyBonus,
    totalScore,
    grade: nativeRankGradeForScore(totalScore),
    wrongGuessCount: detailsAvailable ? clampNumber(Math.floor(Number(raw.wrongGuessCount) || 0), 0, 3) : null,
    unknownCount: detailsAvailable ? clampNumber(Math.floor(Number(raw.unknownCount) || 0), 0, 80) : null,
    firstClear: detailsAvailable && raw.firstClear === true,
    personalBest: detailsAvailable && raw.personalBest === true,
    detailsAvailable,
    rankRulesVersion: NATIVE_RANK_RULES_VERSION,
    citiesVersion: typeof raw.citiesVersion === 'string' ? raw.citiesVersion : '',
  };
}

function emptyNativeRankData(){
  return { version: NATIVE_RANK_STORAGE_VERSION, results: [] };
}

function loadNativeRankData(){
  try{
    const raw = localStorage.getItem(NATIVE_RANK_STORAGE_KEY);
    if(!raw) return emptyNativeRankData();
    const parsed = JSON.parse(raw);
    if(!parsed || parsed.version !== NATIVE_RANK_STORAGE_VERSION || !Array.isArray(parsed.results)){
      return emptyNativeRankData();
    }
    return {
      version: NATIVE_RANK_STORAGE_VERSION,
      results: parsed.results
        .map(normalizeNativeRankRecord)
        .filter(Boolean)
        .sort((a, b) => b.playedAt.localeCompare(a.playedAt))
        .slice(0, NATIVE_RANK_HISTORY_LIMIT),
    };
  }catch(e){
    console.warn('おらマチ: クリア評価記録の読み込みに失敗しました', e);
    return emptyNativeRankData();
  }
}

function saveNativeRankData(data){
  try{
    localStorage.setItem(NATIVE_RANK_STORAGE_KEY, JSON.stringify(data));
    scheduleSupabaseProgressSync();
    return true;
  }catch(e){
    console.warn('おらマチ: クリア評価記録の保存に失敗しました', e);
    return false;
  }
}

