function focusNativeAreaSection(){
  const area = document.getElementById('nativeAreaSection');
  if(!area) return;
  let reduceMotion = false;
  try{ reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches; }
  catch(e){ reduceMotion = false; }
  area.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
}

function buildNativeAreaMapSvg(){
  const paths = japanMapPaths();
  const names = Object.keys(paths);
  if(names.length === 0){
    return '<div class="native-area-map-fallback" aria-label="日本地図">🗾</div>';
  }
  const mapData = window.ORAMACHI_JAPAN_MAP || {};
  const [vx, vy, vw, vh] = mapData.viewBox || JAPAN_MAP_VIEWBOX;
  const colors = {
    '北海道':'#87bce5', '東北':'#75c3b7', '関東':'#80bd79', '中部':'#e8c665',
    '近畿':'#e8a96f', '中国':'#d899aa', '四国':'#aa8ac0', '九州・沖縄':'#d190b5'
  };
  const shapes = names.map(pref => `<path d="${paths[pref]}" fill="${colors[regionOf(pref)] || '#d8d3c6'}"/>`).join('');
  return `<svg class="native-area-map" viewBox="${vx} ${vy} ${vw} ${vh}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" preserveAspectRatio="xMidYMid meet"><g stroke="#fffdf6" stroke-width="1.05" stroke-linejoin="round">${shapes}</g></svg>`;
}

