window.oramachiNativeTabs = Object.freeze({
  open(tab){
    if(!isNativeAppRuntime()) return false;
    if(tab === 'home') renderOpening();
    else if(tab === 'play'){
      // 47都道府県一覧で選択中の「遊ぶ」を再タップした場合は、履歴を
      // 置き換えて二重の遊び方画面を作らず、通常の戻る操作と同じく1階層戻す。
      if(currentNavState.oramachiScreen === 'nativePrefecturePicker'){
        navigateBackOr(renderNativePlayHub);
      }else{
        renderNativePlayHub();
      }
    }
    else if(tab === 'record') renderOfficialDailyLeaderboard();
    else if(tab === 'notice') renderNativeNoticePage();
    else if(tab === 'settings') renderNativeSettingsPage();
    else return false;
    return true;
  }
});

