function getTodaysHomeTrivia(){
  const dateStr=todayJstDateString();
  const m=dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if(!m || !HOME_TRIVIA_365.length) return null;
  const current=Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3]));
  const start=Date.UTC(Number(m[1]),0,1);
  const dayOfYear=Math.floor((current-start)/86400000);
  // 137日ずらし。今日のおらマチと同じ365配列を使っても答え合わせにならない。
  return HOME_TRIVIA_365[(dayOfYear+137)%HOME_TRIVIA_365.length];
}

