const ACHIEVEMENT_CATEGORY_LABELS = {
  all: 'すべて', basic: '基本', speed: 'スピード', streak: '連続正解',
  region: '地方制覇', unique: 'おらマチ独自', attribute: '属性', style: '回答スタイル',
  collection: 'コレクション', hidden: '隠し称号',
};
